\begin{theorem}\label{thm:pointwise}
If~\ref{cond:bounded_K}--\ref{cond:cont_density} hold, then
$\theta_n^{DB}(a_0) - \theta_0(a_0) = \d{P}_n \phi_{\infty,a_0}^* + \fasterthan\left(\{nh\}^{-1/2} + h^2\right),$ 
and $(nh)^{1/2}\d{P}_n \phi_{\infty, a_0}^*\indist N\left(0, V_{K,\tau} f_0(a_0)^{-1}\sigma_0^2(a_0)\right)$, where 
\begin{align*}
V_{K,\tau} &= \int \left\{ K(u) - \tau^3 c_2\frac{(\tau u)^2 - c_2 }{c_4 - c_2^2}  K(\tau u)\right\}^2 \, du \\
&= c_0^* - 2\tau^3 c_2 \frac{\tau^2 c_{2,\tau}^*- c_2c_{0,\tau}^* }{c_4 - c_2^2} + \tau^5 c_2^2 \frac{ c_4^*-2c_2 c_2^* + c_2^2 c_0^*}{\left( c_4 - c_2\right)^2}
\end{align*}
for $c_j \coloneqq \int u^j K(u)\, du$, $c^*_j \coloneqq \int u^j K^2(u)\, du$ and $c^*_{j, \tau}\coloneqq \int u^j K(u)K(\tau u)\, du$. Hence, if $nh^5 = \boundeddet(1)$, then $(nh)^{1/2} \left[ \theta_{n}^{DB}(a_0) - \theta_0(a_0) \right]$ converges in distribution to this same limit. Furthermore, \rev{$\sigma_{n}^2(a_0) \inprob V_{K,\tau} f_0(a_0)^{-1}\sigma_0^2(a_0)$,} so $(nh)^{1/2} \left[ \theta_{n}^{DB}(a_0) - \theta_0(a_0) \right] / \sigma_{n}(a_0) \indist N(0,1)$.%, \rev{so that the confidence interval given in~\eqref{eq:ci} has asymptotic coverage $1-\alpha$, meaning that $P_0(\theta_n^{DB}(a_0) - (nh)^{-1/2}q_{1-\alpha/2} \sigma_n(a_0) \leq  \theta_0(a_0) \leq \theta_n^{DB}(a_0) + (nh)^{-1/2}q_{1-\alpha/2} \sigma_n(a_0)) \rightarrow 1-\alpha$.}
\end{theorem}
